import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type TierListProps = Record<string, any>;

const TierList: React.FC<TierListProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 5,
  tierFontFamily = "Inter",
  tiers = [
    { label: "S", color: "#C29F38" }, // Luxurious matte gold
    { label: "A", color: "#208037" }, // Premium emerald green
    { label: "B", color: "#1C60C0" }, // Deep royal blue
    { label: "C", color: "#6A379E" }, // Rich modern purple
    { label: "D", color: "#7E8081" }, // Sleek light gray
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Layout constants
  const rowWidth = 940 * s;
  const rowHeight = 220 * s;
  const gap = 20 * s;
  const labelWidth = 220 * s;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: gap,
          width: "100%",
          height: "100%",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        {tiers.map((tier, index) => {
          // Staggered entrance animation
          const delay = index * 5;
          const entrance = spring({
            fps,
            frame: frame - delay,
            config: { damping: 15, mass: 0.8, stiffness: 120 },
          });

          const translateX = interpolate(entrance, [0, 1], [-width * 0.2, 0]);
          const scale = interpolate(entrance, [0, 1], [0.95, 1]);
          const opacity = interpolate(entrance, [0, 0.5], [0, 1]);

          return (
            <div
              key={index}
              style={{
                width: rowWidth,
                height: rowHeight,
                transform: `translateX(${translateX}px) scale(${scale})`,
                opacity,
                transition: "none",
                // This outer wrapper creates the metallic/colored border effect
                backgroundColor: tier.color,
                borderRadius: 24 * s,
                padding: 4 * s, // Thickness of the "border"
                backgroundImage:
                  "linear-gradient(180deg, rgba(255,255,255,0.3) 0%, rgba(255,255,255,0) 25%, rgba(0,0,0,0) 75%, rgba(0,0,0,0.5) 100%)",
                boxShadow: `inset 0px ${2 * s}px ${4 * s}px rgba(255,255,255,0.4), inset 0px -${2 * s}px ${4 * s}px rgba(0,0,0,0.4)`,
                display: "flex",
              }}
            >
              {/* Inner container to clip children to border radius */}
              <div
                style={{
                  display: "flex",
                  width: "100%",
                  height: "100%",
                  borderRadius: 20 * s,
                  overflow: "hidden",
                }}
              >
                {/* Left Side: Tier Label */}
                <div
                  style={{
                    width: labelWidth,
                    height: "100%",
                    backgroundColor: tier.color,
                    backgroundImage:
                      "linear-gradient(180deg, rgba(255,255,255,0.15) 0%, rgba(255,255,255,0) 30%, rgba(0,0,0,0) 70%, rgba(0,0,0,0.25) 100%)",
                    boxShadow: `inset 0px ${8 * s}px ${12 * s}px rgba(255,255,255,0.25), inset 0px -${8 * s}px ${12 * s}px rgba(0,0,0,0.3)`,
                    display: "flex",
                    flexDirection: "column",
                    justifyContent: "center",
                    alignItems: "center",
                    borderRight: `${2 * s}px solid rgba(0,0,0,0.5)`,
                    fontFamily:
                      tierFontFamily === "Inter" ? interFamily : "inherit",
                    color: "white",
                  }}
                >
                  <div
                    style={{
                      fontSize: 100 * s,
                      fontWeight: 900,
                      lineHeight: 0.9,
                      textShadow: `0px ${3 * s}px ${6 * s}px rgba(0,0,0,0.4)`,
                      letterSpacing: "-0.02em",
                    }}
                  >
                    {tier.label}
                  </div>
                  <div
                    style={{
                      fontSize: 26 * s,
                      fontWeight: 900,
                      lineHeight: 1,
                      marginTop: 4 * s,
                      letterSpacing: "0.05em",
                      textShadow: `0px ${2 * s}px ${4 * s}px rgba(0,0,0,0.4)`,
                    }}
                  >
                    TIER
                  </div>
                </div>

                {/* Right Side: Empty Content Area */}
                <div
                  style={{
                    flex: 1,
                    height: "100%",
                    backgroundColor: "#161616",
                    backgroundImage:
                      "linear-gradient(180deg, #111111 0%, #1a1a1a 10%), linear-gradient(180deg, rgba(0,0,0,0) 90%, rgba(0,0,0,0.3) 100%)",
                    // Deep inset shadow to create the recessed, premium inner bezel look
                    boxShadow: `inset 0px ${12 * s}px ${20 * s}px rgba(0,0,0,0.9), inset 0px 0px ${8 * s}px rgba(0,0,0,1)`,
                  }}
                />
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default TierList;